public class SurgePricingService
{
    private readonly Dictionary<string, decimal> _zoneMultipliers = new();

    public decimal GetMultiplier(string zone)
    {
        var demand = GetDemand(zone);
        var supply = GetAvailableDrivers(zone);
        var ratio = demand / Math.Max(supply, 1);
        return ratio switch
        {
            < 1 => 1.0m,
            < 2 => 1.2m,
            < 3 => 1.5m,
            < 5 => 2.0m,
            _ => 2.5m
        };
    }
}

public class NotificationService
{
    public async Task NotifyRideStatusAsync(Guid riderId, RideStatus status)
    {
        var message = status switch
        {
            RideStatus.Matched => "Driver assigned! Check driver details.",
            RideStatus.InProgress => "Your ride has started.",
            RideStatus.Completed => "You reached your destination.",
            _ => "Ride status updated."
        };
        await _push.SendAsync(riderId, message);
    }
}
